"""Deterministic read-only check for SQL generated by the agent.

Only a single ``SELECT`` (optionally with CTEs, set operations, subqueries,
``UNNEST`` and window functions) passes.  Anything else — DDL, DML, ``CALL``,
``SET``, ``USE``, ``EXECUTE``, multiple statements, ``SELECT ... INTO``,
table-valued functions, unparseable text — is rejected with a reason.

No LLM is involved: the decision is made purely from the parsed AST.
"""

from __future__ import annotations

from dataclasses import dataclass

from sqlglot import exp

from data_navigator.sqlproc.statements import (
    DEFAULT_DIALECT,
    StatementError,
    is_table_function,
    parse_single_statement,
)

# Node types that can never appear anywhere inside a read-only statement.
_FORBIDDEN_NODES: tuple[type[exp.Expr], ...] = (
    exp.DDL,
    exp.DML,
    exp.Command,
    exp.Set,
    exp.Use,
    exp.Transaction,
    exp.Commit,
    exp.Rollback,
    exp.Grant,
    exp.Describe,
    exp.Analyze,
    exp.Refresh,
    exp.Comment,
    exp.TruncateTable,
    exp.Kill,
    exp.Pragma,
    exp.Copy,
    exp.Into,
    exp.Lock,
)


@dataclass(frozen=True)
class GuardResult:
    """Outcome of :func:`readonly_guard`."""

    allowed: bool
    reason: str | None = None
    statement_type: str | None = None

    @property
    def rejected(self) -> bool:
        return not self.allowed


def _reject(reason: str, statement_type: str | None = None) -> GuardResult:
    return GuardResult(allowed=False, reason=reason, statement_type=statement_type)


def readonly_guard(sql: str, dialect: str = DEFAULT_DIALECT) -> GuardResult:
    """Return whether *sql* is a single read-only ``SELECT`` statement."""
    if not sql or not sql.strip():
        return _reject("empty statement")
    try:
        statement = parse_single_statement(sql, dialect)
    except StatementError as error:
        return _reject(str(error))
    return check_readonly_expression(statement)


def check_readonly_expression(statement: exp.Expr) -> GuardResult:
    """AST-level variant of :func:`readonly_guard` for already-parsed statements."""
    statement_type = type(statement).__name__.upper()
    if not isinstance(statement, exp.Select | exp.SetOperation):
        return _reject(f"only SELECT statements are allowed, got {statement_type}", statement_type)

    for node in statement.walk():
        if isinstance(node, _FORBIDDEN_NODES):
            kind = type(node).__name__.upper()
            return _reject(f"statement contains a non-read-only element: {kind}", statement_type)
        if isinstance(node, exp.Select) and node.args.get("into") is not None:
            return _reject("SELECT ... INTO is not allowed", statement_type)
        if isinstance(node, exp.Table) and is_table_function(node):
            return _reject("table-valued functions are not allowed", statement_type)

    return GuardResult(allowed=True, statement_type=statement_type)


def apply_row_limit(statement: exp.Expr, max_rows: int) -> exp.Expr:
    """Return a copy of *statement* whose result is capped at *max_rows* rows.

    An existing ``LIMIT`` that is already an integer literal not larger than
    *max_rows* is kept; any other ``LIMIT``/``FETCH`` is replaced.  The input must
    have passed :func:`check_readonly_expression`.
    """
    if max_rows < 1:
        msg = "max_rows must be at least 1"
        raise ValueError(msg)
    if not isinstance(statement, exp.Query):
        msg = "row limits can only be applied to queries"
        raise TypeError(msg)
    query = statement.copy()
    existing = query.args.get("limit")
    if isinstance(existing, exp.Limit):
        value = existing.expression
        if (
            isinstance(value, exp.Literal)
            and not value.is_string
            and value.this.isdigit()
            and int(value.this) <= max_rows
        ):
            return query
    return query.limit(max_rows, copy=False)
